const SENSITIVE_KEYS = new Set([
    'authToken',
    'encryptedAuthToken',
    'password',
    'partnerUserSecret',
    'partnerPassword',
    'twoFactorAuthCode',
    'idToken',
    'token',
    'validateCode',
    'autoGeneratedPassword',
    'autoGeneratedLogin',
    'oldDotCurrentAuthToken',
    'oldDotCurrentEncryptedAuthToken',
    'oldDotAutoGeneratedPassword',
    'apiKey',
    'currentAuthToken',
    'clientSecret',
    'cardNumber',
    'cardCVV',
    // Expensify Card PIN commands send the PIN, and the card reveal commands return the PIN and full card details under these names.
    'pin',
    'pan',
    'cvv',
    'expiration',
    'signedChallenge',
    'nonce',
    'nonceSignature',
    'certificates',
    'encryptedPassData',
    'activationData',
    'ephemeralPublicKey',
    'opaquePaymentCard',
    'ssn',
    'ssnLast4',
    'accountNumber',
    'routingNumber',
    'plaidAccessToken',
    'publicToken',
    'intacctPassword',
    'netSuiteTokenID',
    'netSuiteTokenSecret',
    // These are sent as JSON strings, so key matching can't see the SSN and bank fields inside them.
    'inputs',
    'beneficialOwners',
    'additionalData',
]);

const REDACTED = '<redacted>';

function sanitizeLogParams<T>(params: T, depth = 0, parentCommand?: string): T {
    if (depth > 5 || params == null || typeof params !== 'object') {
        return params;
    }

    if (Array.isArray(params)) {
        return (params as unknown[]).map((item) => sanitizeLogParams(item, depth + 1, parentCommand)) as unknown as T;
    }

    const command = 'command' in params && typeof params.command === 'string' ? params.command : parentCommand;
    const sanitized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(params)) {
        // This query includes card evidence such as exact spend and employee details.
        if (SENSITIVE_KEYS.has(key) || (command === 'GetInsightsExplanation' && key === 'jsonQuery')) {
            sanitized[key] = REDACTED;
        } else if (value != null && typeof value === 'object') {
            sanitized[key] = sanitizeLogParams(value, depth + 1, command);
        } else {
            sanitized[key] = value;
        }
    }

    return sanitized as T;
}

/**
 * Redact sensitive segments from URL paths before logging.
 * Handles /v/:accountID/:validateCode and /u/:accountID/:validateCode patterns,
 * and strips query parameters that may contain tokens.
 */
function sanitizeUrlForLogging(url: string): string {
    return (
        url
            // Redact validateCode in /v/:accountID/:validateCode and /u/:accountID/:validateCode
            .replace(/\/([vu])\/(\d+)\/[^/?#]+/, '/$1/$2/<redacted>')
            // Strip query string (may contain authToken, token, etc.)
            .replace(/\?.*$/, '?<redacted>')
    );
}

export default sanitizeLogParams;
export {sanitizeUrlForLogging};
